  let oldPosition = 0;
  let newPosition = 0;
  while (i < script.length) {
    if (script[i].op === 'equal') {
      i++;
      oldPosition++;
      newPosition++;
      continue;
    }

    const start = Math.max(0, i - context);
    const oldIndex = oldPosition - (i - start);
    const newIndex = newPosition - (i - start);
