      const changeEnd = next;
      while (next < script.length && script[next].op === 'equal') next++;
      const gap = next - changeEnd;
      if (next === script.length || gap > 2 * context) {
        end = changeEnd + Math.min(context, gap);
        break;
      }
    }

    const lines = [];
    let oldLines = 0;
    let newLines = 0;
    for (let j = start; j < end; j++) {
      const { op, line } = script[j];
      if (op === 'equal') {
        lines.push(' ' + line);
        oldLines++;
        newLines++;
      } else if (op === 'delete') {
        lines.push('-' + line);
        oldLines++;
      } else {
        lines.push('+' + line);
        newLines++;
      }
    }
    hunks.push({
      oldStart: oldIndex + (oldLines === 0 ? 0 : 1),
      oldLines,
      newStart: newIndex + (newLines === 0 ? 0 : 1),
      newLines,
      lines,
    });
    i = end;
    oldPosition = oldIndex + oldLines;
    newPosition = newIndex + newLines;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  const result = [];
  let oldPosition = 0;
  for (let i = 0; i < hunks.length; i++) {
    const hunk = hunks[i];
    if (hunk === null || typeof hunk !== 'object') rejectHunk(i);
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (!Number.isSafeInteger(oldStart) || !Number.isSafeInteger(oldLines) ||
        !Number.isSafeInteger(newStart) || !Number.isSafeInteger(newLines) ||
