    const oldEnd = oldIndex + oldLines;
    let added = 0;
    for (const entry of lines) {
      if (typeof entry !== 'string' || entry.length === 0) rejectHunk(i);
      const prefix = entry[0];
      if (prefix !== ' ' && prefix !== '-' && prefix !== '+') rejectHunk(i);
      const line = entry.slice(1);
      if (prefix !== '+') {
        if (oldPosition >= oldEnd || a[oldPosition] !== line) rejectHunk(i);
        oldPosition++;
      }
      if (prefix !== '-') {
        result.push(line);
        added++;
      }
    }
