const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const table = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      table[i][j] = a[i - 1] === b[j - 1] ? table[i - 1][j - 1] + 1 : Math.max(table[i - 1][j], table[i][j - 1]);
    }
  }
  return table[a.length][b.length];
}

function referenceHunks(script, context) {
  const regions = [];
  for (let i = 0; i < script.length; i++) {
    if (script[i].op === 'equal') continue;
    let start = i;
    let end = i + 1;
    for (let n = 0; n < context && start > 0 && script[start - 1].op === 'equal'; n++) start--;
    for (let n = 0; n < context && end < script.length && script[end].op === 'equal'; n++) end++;
    const previous = regions[regions.length - 1];
    if (previous && previous.end >= start) previous.end = Math.max(previous.end, end);
    else regions.push({ start, end });
  }
  return regions.map(({ start, end }) => {
    const oldBefore = script.slice(0, start).filter(entry => entry.op !== 'insert').length;
    const newBefore = script.slice(0, start).filter(entry => entry.op !== 'delete').length;
    const entries = script.slice(start, end);
    const oldLines = entries.filter(entry => entry.op !== 'insert').length;
    const newLines = entries.filter(entry => entry.op !== 'delete').length;
    return {
      oldStart: oldBefore + (oldLines ? 1 : 0), oldLines,
      newStart: newBefore + (newLines ? 1 : 0), newLines,
      lines: entries.map(entry => ({ equal: ' ', delete: '-', insert: '+' })[entry.op] + entry.line),
    };
  });
}

const inputs = [Object.freeze([])];
let level = [[]];
for (let length = 1; length <= 4; length++) {
  level = level.flatMap(lines => ['', '+leading', '-leading'].map(line => Object.freeze([...lines, line])));
  inputs.push(...level);
}
let pairs = 0;
let roundtrips = 0;
for (const a of inputs) {
  for (const b of inputs) {
    const script = diffLines(a, b);
    assert.deepEqual(script.filter(entry => entry.op !== 'insert').map(entry => entry.line), a);
    assert.deepEqual(script.filter(entry => entry.op !== 'delete').map(entry => entry.line), b);
    assert.equal(script.filter(entry => entry.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
    assert.deepEqual(diffLines(a, b), script);
    let sawInsert = false;
    for (const entry of script) {
      if (entry.op === 'equal') sawInsert = false;
      else if (entry.op === 'insert') sawInsert = true;
      else { assert.equal(entry.op, 'delete'); assert.equal(sawInsert, false); }
    }
    for (const context of [0, 1, 2, 3]) {
      const hunks = unifiedHunks(a, b, { context });
      assert.deepEqual(hunks, referenceHunks(script, context));
      for (const hunk of hunks) { Object.freeze(hunk.lines); Object.freeze(hunk); }
      Object.freeze(hunks);
      assert.deepEqual(applyHunks(a, hunks), b);
      roundtrips++;
    }
    pairs++;
  }
}
const original = Object.freeze(['a', 'b', 'c']);
const copy = applyHunks(original, []);
assert.deepEqual(copy, original);
assert.notEqual(copy, original);
const good = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
const invalid = [
  null, undefined, 3, {},
  { ...good, oldStart: 0 }, { ...good, newStart: 0 },
  { ...good, oldStart: 5 }, { ...good, newStart: 3 },
  { ...good, oldStart: 1.5 }, { ...good, oldLines: -1 },
  { ...good, oldLines: NaN }, { ...good, newLines: Infinity },
  { ...good, lines: null }, { ...good, lines: [null] },
  { ...good, lines: [''] }, { ...good, lines: ['?b'] },
  { ...good, lines: ['-wrong', '+B'] },
  { ...good, lines: [' wrong'] },
  { ...good, oldLines: 2 }, { ...good, newLines: 2 },
  { ...good, lines: ['-b', '-c', '+B'] },
  { ...good, oldLines: 3 },
  { ...good, oldLines: 0, oldStart: 4 },
];
for (const hunk of invalid) assert.throws(() => applyHunks(original, [hunk]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(original, [good, good]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(original, [good, { oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' a'] }]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(original, [good, { oldStart: 3, oldLines: 1, newStart: 4, newLines: 1, lines: [' c'] }]), /hunk 1 does not apply/);
assert.deepEqual(applyHunks(['a'], [
  { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] },
  { oldStart: 0, oldLines: 0, newStart: 2, newLines: 1, lines: ['+y'] },
]), ['x', 'y', 'a']);
assert.deepEqual(unifiedHunks(['a', 'b'], ['a', 'B']), unifiedHunks(['a', 'b'], ['a', 'B'], { context: 3 }));
console.log(`Exhaustive: ${pairs} minimal deterministic scripts, ${roundtrips} exact hunks and frozen-input roundtrips; ${invalid.length + 3} malformed/overlapping hunk checks passed.`);

for (const repeated of [false, true]) {
  const a = Array.from({ length: 20000 }, (_, i) => repeated ? String(i % 3) : `line ${i}`);
  const b = a.slice();
  b.splice(0, 0, '+top');
  b.splice(5000, 1, 'replacement');
  b.splice(15000, 2);
  b.push('-bottom');
  const start = performance.now();
  const script = diffLines(a, b);
  const hunks = unifiedHunks(a, b);
  const result = applyHunks(a, hunks);
  const elapsed = performance.now() - start;
  assert.deepEqual(result, b);
  assert.equal(script.filter(entry => entry.op !== 'equal').length, 6);
  assert.ok(elapsed < 1000, `20,000-line path took ${elapsed} ms`);
  console.log(`20,000 ${repeated ? 'repetitive' : 'unique'} lines: diff + hunks + apply ${elapsed.toFixed(2)} ms.`);
}
